// tracks returns all simplified tracks as GeoJSON. Filtering happens in the
// browser, so changing a filter never needs a request.
func (s *server) tracks(w http.ResponseWriter, r *http.Request) {
	list, err := s.Store.Tracks(r.Context(), store.ListFilter{})
	if err != nil {
		s.serverError(w, "load tracks", err)
		return
	}
	features := make([]trackFeature, 0, len(list))
	for _, t := range list {
		ls, err := geo.DecodePolyline(t.Polyline)
		if err != nil || len(ls) < 2 {
			s.Logger.Warn("skip invalid track", "activity", t.ID, "err", err)
			continue
		}
		coords := make([][2]float64, len(ls))
		for i, p := range ls {
			coords[i] = [2]float64{p.Lon(), p.Lat()}
		}
		label := sport.Label(t.Sport, t.SubSport)
		if t.Name != "" {
			label = t.Name
		}
		features = append(features, trackFeature{
			Type:     "Feature",
			ID:       t.ID,
			Geometry: trackGeometry{Type: "LineString", Coordinates: coords},
			Properties: trackProps{
				ID: t.ID, Cat: sport.CategoryOf(t.Sport).ID, Label: label,
				T: t.StartTime.Unix() + int64(t.TZOffsetS), Km: math.Round(t.DistanceM/100) / 10,
			},
		})
	}
	w.Header().Set("Content-Type", "application/geo+json")
	w.Header().Set("Cache-Control", "no-cache")
	_ = json.NewEncoder(w).Encode(map[string]any{"type": "FeatureCollection", "features": features})
}
